"; header += "<html>
"; header += "<head>
"; header += "<meta http-equiv="content-type" content="text/html; charset=utf-8">
"; header += "<title>" + "Preview" + "</title>
"; header += "<style type="text/css">
"; header += "<!--
"; header += "body{color:grey; font-size:10pt;font-family: @Arial Unicode MS;}
"; header += "span{color:black;cursor: hand;}
"; //real-time preview related styles header += ".activesegment{color:red;background-color: silver;cursor: hand;}
"; header += ".normal{color:black;background-color: white;cursor: hand;}
"; header += "//-->
"; header += "</style>
"; //real-time preview related JavaScript functions header += "<script type="text/javascript">
"; header += "<!--
"; header += "function setActiveStyle(objDivID)
"; header += "{
"; header += "document.getElementById(objDivID).className = 'activesegment';
"; header += "}
"; header += "function setNormalStyle(objDivID)
"; header += "{
"; header += "document.getElementById(objDivID).className = 'normal';
"; header += "}
"; header += "//-->
"; header += "</script>
"; header += "</head>
